// This policy setting allows you to determine whether users can elect to download files from Edge
// in the container and persist files them from container to the host operating system.
//
// Default: 0.
// Supported from OS build 10.0.17134 (CSP v1.2).
func (s *WindowsDefenderApplicationGuard) DeleteSettingsSaveFilesToHost(ctx context.Context) error {
	return s.c.Delete(ctx, URISettingsSaveFilesToHost)
}

// GetStatus reads ./Device/Vendor/MSFT/WindowsDefenderApplicationGuard/Status.
// Returns bitmask that indicates status of Application Guard installation and pre-requisites on
// the device. Bit 0 - Set to 1 when Application Guard is enabled into enterprise manage mode. Bit
// 1 - Set to 1 when the client machine is Hyper-V capable. Bit 2 - Set to 1 when the client
// machine has a valid OS license and SKU. Bit 3 - Set to 1 when Application Guard installed on the
// client machine. Bit 4 - Set to 1 when required Network Isolation Policies are configured. Bit 5
// - Set to 1 when the client machine meets minimum hardware requirements. Bit 6 - Set to 1 when
// system reboot is required.
func (s *WindowsDefenderApplicationGuard) GetStatus(ctx context.Context) (int64, error) {
	v, err := s.c.Get(ctx, URIStatus)
	if err != nil {
		return 0, err
	}
	return v.Int()
}
